<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class ChampionshipMatch extends Model {protected $guarded=[];protected function casts():array{return ['scheduled_at'=>'datetime','not_before_at'=>'datetime','called_at'=>'datetime','started_at'=>'datetime','completed_at'=>'datetime','entry1_checked_in_at'=>'datetime','entry2_checked_in_at'=>'datetime','score_data'=>'array','result_verified_at'=>'datetime'];}public function draw(){return $this->belongsTo(ChampionshipDraw::class,'championship_draw_id');}public function entry1(){return $this->belongsTo(ChampionshipEntry::class,'entry1_id');}public function entry2(){return $this->belongsTo(ChampionshipEntry::class,'entry2_id');}public function winner(){return $this->belongsTo(ChampionshipEntry::class,'winner_entry_id');}public function loser(){return $this->belongsTo(ChampionshipEntry::class,'loser_entry_id');}public function facility(){return $this->belongsTo(Facility::class);}public function booking(){return $this->belongsTo(Booking::class);} }
